import{_ as d,C as c,c as s,o as r,av as o,G as i}from"./chunks/framework.BPD5u9g7.js";const A=JSON.parse('{"title":"Andor拉曼光谱数据处理助手","description":"","frontmatter":{},"headers":[],"relativePath":"chemometrics/andor-raman/index.md","filePath":"index/chemometrics/andor-raman/index.md","lastUpdated":1765362412000}'),t={name:"chemometrics/andor-raman/index.md"};function n(l,e,p,m,_,h){const a=c("AndorAscsToXlsx");return r(),s("div",null,[e[0]||(e[0]=o('<h1 id="andor拉曼光谱数据处理助手" tabindex="-1">Andor拉曼光谱数据处理助手 <a class="header-anchor" href="#andor拉曼光谱数据处理助手" aria-label="Permalink to &quot;Andor拉曼光谱数据处理助手&quot;">​</a></h1><div class="warning custom-block github-alert"><p class="custom-block-title">受限于Andor数据文件的闭源编码格式，该功能需分2步完成：</p><p></p><ol><li><p>将Andor拉曼光谱仪的<code>.sif</code>数据文件转为txt化的<code>.asc</code>文档文件。</p></li><li><p>一键将大量<code>.asc</code>数据文档文件合并导出为一个excel表格文件。</p></li></ol></div><h2 id="第一步-处理-sif文件" tabindex="-1">第一步：处理.sif文件 <a class="header-anchor" href="#第一步-处理-sif文件" aria-label="Permalink to &quot;第一步：处理.sif文件&quot;">​</a></h2><ol><li><p>下载脚本文件：<a href="/assets/andorSifsToAscs.pgm" download="andorSifsToAscs.pgm">andorSifsToAscs.pgm</a></p></li><li><p>将想要转换格式的<code>.sif</code>文件统一放进一个文件夹内；</p></li><li><p>将本<code>.pgm</code>脚本文件也放进<code>.sif</code>文件夹内；</p></li><li><p>在Andor SOLIS软件里，&quot;File&quot; - &quot;Run Program By Filename&quot;，选择本<code>.pgm</code>脚本文件运行，即可批量生成<code>.asc</code>文件。 详细说明见下“数据文件合并”。</p></li></ol><h2 id="第二步-数据文件合并" tabindex="-1">第二步：数据文件合并 <a class="header-anchor" href="#第二步-数据文件合并" aria-label="Permalink to &quot;第二步：数据文件合并&quot;">​</a></h2><ol><li><p>直接读取上一步得到<code>.asc</code>文件的<strong>文件夹</strong>即可。（会自动过滤<code>.sif</code>等其它无关文件）</p></li><li><p>一键下载excel文件，即所有<code>.asc</code>文件合并后的excel表格。</p></li></ol>',6)),i(a),e[1]||(e[1]=o('<h2 id="其它" tabindex="-1">其它 <a class="header-anchor" href="#其它" aria-label="Permalink to &quot;其它&quot;">​</a></h2><p>本来想“一站式”解决问题的，但Andor的sif文件有自己的编码，外部解码转码的工作量很大，所以想到用Andor自己提供的接口来实现转码，也就是所写的<code>.pgm</code>脚本文件。</p><p>但是Andor脚本接口是闭源的，功能实现非常有限，要用Andor脚本来实现一键批量转excel的话太繁琐了。所以又写了本WebApp，来实现<code>.asc</code>文件一键汇总为Excel表格的功能。</p><p>第一步的<code>.pgm</code>脚本文件功能很简单，就是读取<code>.sif</code>，另存<code>.asc</code>。感兴趣的同学可以用文本文档打开<code>.pgm</code>脚本文件查看注释或修改脚本。</p><p>本WebApp的功能也很简单，挂载文件夹之后，获取文件夹内的文件句柄，根据文件扩展名过滤。然后就是以句柄获取文件内容 + 转为excel格式等操作。感兴趣的同学可以从 <a href="/phys-chem/about/">关于</a> 那里查看源码。</p>',5))])}const u=d(t,[["render",n]]);export{A as __pageData,u as default};
